-- Creators Campus marketplace — 0001_init.sql
-- Tables + Row Level Security. Run FIRST in the Supabase SQL editor.
-- Safe to re-run: tables use IF NOT EXISTS, policies are dropped first.
--
-- Notes:
-- * ids are uuids generated by the database. The string ids in
--   lib/catalog.ts ('cat-social-premium', 'prod-x-premium', ...) are seed
--   reference keys only — the seed matches rows by slug, not by id.
-- * profiles.id references auth.users(id): a profile row is created at
--   sign-up (see lib/auth.tsx), so profiles must allow a user to INSERT
--   their own row.

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

create table if not exists public.categories (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique,
  description text,
  icon text,
  sort_order int not null default 0,
  active boolean not null default true,
  created_at timestamptz not null default now()
);

create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  email text not null,
  full_name text,
  role text not null default 'customer' check (role in ('customer', 'admin', 'support')),
  created_at timestamptz not null default now()
);

create table if not exists public.products (
  id uuid primary key default gen_random_uuid(),
  category_id uuid references public.categories (id) on delete set null,
  name text not null,
  slug text not null unique,
  description text not null default '',
  features jsonb not null default '[]'::jsonb,
  delivery_type text not null default 'manual' check (delivery_type in ('manual', 'activation_code')),
  delivery_instructions text,
  stock int not null default 50,
  active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);

create table if not exists public.plans (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  name text not null,
  duration_months int not null,
  price numeric(10, 2) not null,
  compare_price numeric(10, 2),
  active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);

create table if not exists public.coupons (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  type text not null check (type in ('percent', 'fixed')),
  value numeric(10, 2) not null,
  min_order numeric(10, 2) not null default 0,
  max_uses int,
  used_count int not null default 0,
  expires_at timestamptz,
  active boolean not null default true,
  created_at timestamptz not null default now()
);

create table if not exists public.suppliers (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  contact text,
  email text,
  notes text,
  created_at timestamptz not null default now()
);

create table if not exists public.orders (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id),
  order_number text not null unique,
  status text not null default 'pending_payment' check (status in ('pending_payment', 'awaiting_verification', 'verified', 'delivering', 'completed', 'cancelled', 'refunded')),
  total numeric(10, 2) not null,
  currency text not null default 'USD',
  coupon_code text,
  discount numeric(10, 2) not null default 0,
  created_at timestamptz not null default now()
);

create table if not exists public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  product_id uuid references public.products (id),
  plan_id uuid references public.plans (id),
  quantity int not null default 1,
  price numeric(10, 2) not null,
  product_name text,
  plan_name text,
  created_at timestamptz not null default now()
);

create table if not exists public.payments (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  method text not null,
  transaction_id text,
  proof_url text,
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  submitted_at timestamptz not null default now(),
  reviewed_at timestamptz,
  note text,
  created_at timestamptz not null default now()
);

create table if not exists public.tickets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id),
  subject text not null,
  status text not null default 'open' check (status in ('open', 'in_progress', 'resolved', 'closed')),
  priority text not null default 'normal',
  created_at timestamptz not null default now()
);

create table if not exists public.ticket_replies (
  id uuid primary key default gen_random_uuid(),
  ticket_id uuid not null references public.tickets (id) on delete cascade,
  user_id uuid references public.profiles (id),
  message text not null,
  created_at timestamptz not null default now()
);

create table if not exists public.stock_movements (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id),
  change int not null,
  reason text,
  created_at timestamptz not null default now(),
  created_by uuid references public.profiles (id)
);

create table if not exists public.deliveries (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  type text,
  activation_code text,
  instructions text,
  delivered_at timestamptz,
  delivered_by uuid references public.profiles (id),
  created_at timestamptz not null default now()
);

create table if not exists public.refunds (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  amount numeric(10, 2) not null,
  reason text,
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'completed')),
  created_at timestamptz not null default now()
);

create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id),
  title text not null,
  body text,
  link text,
  read boolean not null default false,
  created_at timestamptz not null default now()
);

create table if not exists public.activity_logs (
  id uuid primary key default gen_random_uuid(),
  admin_id uuid references public.profiles (id),
  action text not null,
  details jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.settings (
  id uuid primary key default gen_random_uuid(),
  key text not null unique,
  value jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Indexes (foreign keys, slugs, order numbers)
-- ---------------------------------------------------------------------------

create index if not exists idx_products_category_id on public.products (category_id);
create index if not exists idx_products_slug on public.products (slug);
create index if not exists idx_categories_slug on public.categories (slug);
create index if not exists idx_plans_product_id on public.plans (product_id);
create index if not exists idx_orders_user_id on public.orders (user_id);
create index if not exists idx_orders_order_number on public.orders (order_number);
create index if not exists idx_orders_status_created on public.orders (status, created_at desc);
create index if not exists idx_order_items_order_id on public.order_items (order_id);
create index if not exists idx_order_items_product_id on public.order_items (product_id);
create index if not exists idx_order_items_plan_id on public.order_items (plan_id);
create index if not exists idx_payments_order_id on public.payments (order_id);
create index if not exists idx_tickets_user_id on public.tickets (user_id);
create index if not exists idx_ticket_replies_ticket_id on public.ticket_replies (ticket_id);
create index if not exists idx_ticket_replies_user_id on public.ticket_replies (user_id);
create index if not exists idx_stock_movements_product_id on public.stock_movements (product_id);
create index if not exists idx_deliveries_order_id on public.deliveries (order_id);
create index if not exists idx_refunds_order_id on public.refunds (order_id);
create index if not exists idx_notifications_user_id on public.notifications (user_id);
create index if not exists idx_activity_logs_admin_id on public.activity_logs (admin_id);
create index if not exists idx_coupons_code on public.coupons (code);

-- ---------------------------------------------------------------------------
-- Helper: is_admin()
-- SECURITY DEFINER so the profiles lookup inside bypasses RLS (otherwise
-- the admin policies on profiles would recurse). Only checks the caller's
-- own profile row; returns false when not signed in.
-- ---------------------------------------------------------------------------

create or replace function public.is_admin()
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'admin'
  );
$$;

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------

alter table public.categories      enable row level security;
alter table public.products        enable row level security;
alter table public.plans           enable row level security;
alter table public.profiles        enable row level security;
alter table public.orders          enable row level security;
alter table public.order_items     enable row level security;
alter table public.payments        enable row level security;
alter table public.tickets         enable row level security;
alter table public.ticket_replies  enable row level security;
alter table public.coupons         enable row level security;
alter table public.suppliers       enable row level security;
alter table public.stock_movements enable row level security;
alter table public.deliveries      enable row level security;
alter table public.refunds         enable row level security;
alter table public.notifications   enable row level security;
alter table public.activity_logs   enable row level security;
alter table public.settings        enable row level security;

-- --- Public catalog: anyone (anon + signed-in) can read active rows only.
drop policy if exists "Public can read active categories" on public.categories;
create policy "Public can read active categories" on public.categories
  for select to anon, authenticated using (active = true);

drop policy if exists "Public can read active products" on public.products;
create policy "Public can read active products" on public.products
  for select to anon, authenticated using (active = true);

drop policy if exists "Public can read active plans" on public.plans;
create policy "Public can read active plans" on public.plans
  for select to anon, authenticated using (active = true);

-- --- Profiles: a user reads/inserts/updates only their own row.
-- (INSERT is needed because sign-up creates the profile row, lib/auth.tsx.)
drop policy if exists "Users can read own profile" on public.profiles;
create policy "Users can read own profile" on public.profiles
  for select to authenticated using (id = auth.uid());

drop policy if exists "Users can insert own profile" on public.profiles;
create policy "Users can insert own profile" on public.profiles
  for insert to authenticated with check (id = auth.uid());

drop policy if exists "Users can update own profile" on public.profiles;
create policy "Users can update own profile" on public.profiles
  for update to authenticated using (id = auth.uid()) with check (id = auth.uid());

-- --- Orders: own rows only (select / insert / update).
drop policy if exists "Users can read own orders" on public.orders;
create policy "Users can read own orders" on public.orders
  for select to authenticated using (user_id = auth.uid());

drop policy if exists "Users can insert own orders" on public.orders;
create policy "Users can insert own orders" on public.orders
  for insert to authenticated with check (user_id = auth.uid());

drop policy if exists "Users can update own orders" on public.orders;
create policy "Users can update own orders" on public.orders
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- --- Order items: via ownership of the parent order.
drop policy if exists "Users can read own order items" on public.order_items;
create policy "Users can read own order items" on public.order_items
  for select to authenticated using (
    exists (select 1 from public.orders o where o.id = order_items.order_id and o.user_id = auth.uid())
  );

drop policy if exists "Users can insert own order items" on public.order_items;
create policy "Users can insert own order items" on public.order_items
  for insert to authenticated with check (
    exists (select 1 from public.orders o where o.id = order_items.order_id and o.user_id = auth.uid())
  );

drop policy if exists "Users can update own order items" on public.order_items;
create policy "Users can update own order items" on public.order_items
  for update to authenticated using (
    exists (select 1 from public.orders o where o.id = order_items.order_id and o.user_id = auth.uid())
  ) with check (
    exists (select 1 from public.orders o where o.id = order_items.order_id and o.user_id = auth.uid())
  );

-- --- Payments: via ownership of the parent order.
drop policy if exists "Users can read own payments" on public.payments;
create policy "Users can read own payments" on public.payments
  for select to authenticated using (
    exists (select 1 from public.orders o where o.id = payments.order_id and o.user_id = auth.uid())
  );

drop policy if exists "Users can insert own payments" on public.payments;
create policy "Users can insert own payments" on public.payments
  for insert to authenticated with check (
    exists (select 1 from public.orders o where o.id = payments.order_id and o.user_id = auth.uid())
  );

drop policy if exists "Users can update own payments" on public.payments;
create policy "Users can update own payments" on public.payments
  for update to authenticated using (
    exists (select 1 from public.orders o where o.id = payments.order_id and o.user_id = auth.uid())
  ) with check (
    exists (select 1 from public.orders o where o.id = payments.order_id and o.user_id = auth.uid())
  );

-- --- Tickets: own rows only.
drop policy if exists "Users can read own tickets" on public.tickets;
create policy "Users can read own tickets" on public.tickets
  for select to authenticated using (user_id = auth.uid());

drop policy if exists "Users can insert own tickets" on public.tickets;
create policy "Users can insert own tickets" on public.tickets
  for insert to authenticated with check (user_id = auth.uid());

drop policy if exists "Users can update own tickets" on public.tickets;
create policy "Users can update own tickets" on public.tickets
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- --- Ticket replies: read replies on own tickets (or own replies);
-- insert only on own tickets, as yourself.
drop policy if exists "Users can read replies on own tickets" on public.ticket_replies;
create policy "Users can read replies on own tickets" on public.ticket_replies
  for select to authenticated using (
    user_id = auth.uid()
    or exists (select 1 from public.tickets t where t.id = ticket_replies.ticket_id and t.user_id = auth.uid())
  );

drop policy if exists "Users can insert replies on own tickets" on public.ticket_replies;
create policy "Users can insert replies on own tickets" on public.ticket_replies
  for insert to authenticated with check (
    user_id = auth.uid()
    and exists (select 1 from public.tickets t where t.id = ticket_replies.ticket_id and t.user_id = auth.uid())
  );

drop policy if exists "Users can update own replies" on public.ticket_replies;
create policy "Users can update own replies" on public.ticket_replies
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- --- Notifications: own rows only (update = marking read).
drop policy if exists "Users can read own notifications" on public.notifications;
create policy "Users can read own notifications" on public.notifications
  for select to authenticated using (user_id = auth.uid());

drop policy if exists "Users can insert own notifications" on public.notifications;
create policy "Users can insert own notifications" on public.notifications
  for insert to authenticated with check (user_id = auth.uid());

drop policy if exists "Users can update own notifications" on public.notifications;
create policy "Users can update own notifications" on public.notifications
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- --- Deliveries / refunds: customers can read the ones tied to their orders.
drop policy if exists "Users can read own deliveries" on public.deliveries;
create policy "Users can read own deliveries" on public.deliveries
  for select to authenticated using (
    exists (select 1 from public.orders o where o.id = deliveries.order_id and o.user_id = auth.uid())
  );

drop policy if exists "Users can read own refunds" on public.refunds;
create policy "Users can read own refunds" on public.refunds
  for select to authenticated using (
    exists (select 1 from public.orders o where o.id = refunds.order_id and o.user_id = auth.uid())
  );

-- --- Admins: full access (ALL) on every table.
drop policy if exists "Admins full access to categories" on public.categories;
create policy "Admins full access to categories" on public.categories
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to products" on public.products;
create policy "Admins full access to products" on public.products
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to plans" on public.plans;
create policy "Admins full access to plans" on public.plans
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to profiles" on public.profiles;
create policy "Admins full access to profiles" on public.profiles
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to orders" on public.orders;
create policy "Admins full access to orders" on public.orders
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to order_items" on public.order_items;
create policy "Admins full access to order_items" on public.order_items
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to payments" on public.payments;
create policy "Admins full access to payments" on public.payments
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to tickets" on public.tickets;
create policy "Admins full access to tickets" on public.tickets
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to ticket_replies" on public.ticket_replies;
create policy "Admins full access to ticket_replies" on public.ticket_replies
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to coupons" on public.coupons;
create policy "Admins full access to coupons" on public.coupons
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to suppliers" on public.suppliers;
create policy "Admins full access to suppliers" on public.suppliers
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to stock_movements" on public.stock_movements;
create policy "Admins full access to stock_movements" on public.stock_movements
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to deliveries" on public.deliveries;
create policy "Admins full access to deliveries" on public.deliveries
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to refunds" on public.refunds;
create policy "Admins full access to refunds" on public.refunds
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to notifications" on public.notifications;
create policy "Admins full access to notifications" on public.notifications
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to activity_logs" on public.activity_logs;
create policy "Admins full access to activity_logs" on public.activity_logs
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Admins full access to settings" on public.settings;
create policy "Admins full access to settings" on public.settings
  for all to authenticated using (public.is_admin()) with check (public.is_admin());
